/**
 * The command line: argv into an AppConfig.
 *
 * Split out of index.ts, which runs `main()` at import time unless
 * `SSH_MCP_DISABLE_MAIN=1` is set *and* `SSH_MCP_TEST` is not `1` — the gate is a
 * disjunction, so the test variable overrides the disable one. That made every test of a
 * pure argv helper a test that could start connecting to real hosts on a machine with a
 * real config; one of them carried a six-line comment and a `vi.stubEnv` about exactly
 * that, both removed by this split. Nothing in this file has a side effect at import
 * time, so importing it is safe.
 *
 * Not *everything* argv-shaped lives here: index.ts still reads the transport, OTEL and
 * OPA flags at the wiring site, where they are used. What moved is the part that had to
 * escape the boot gate to be testable.
 */

import { loadConfigWithDigest, getConfigPath } from './config/loader.js';
import { OperatorError, ConfigNotFoundError, UnconfiguredError } from './errors.js';
import type { AclFinding, AclOptions } from './config/windows-acl.js';
import { HOST_GROUPS } from './policy/engine.js';
import type { HostKeyMode } from './ssh/host-key.js';
import type { AppConfig, Profile, Defaults } from './types.js';
import type { ConfigSource, LoadedConfig } from './config/loaded.js';

/**
 * Whether the operator asked for a quick start at all.
 *
 * Presence, not truthiness — the same #91 trap `flagEnabled` was written for. `parseArgv`
 * stores `null` for a flag written without `=` and drops bare words, so all three of
 * `--host example.com --user root` (space instead of `=`, the commonest slip), `--host`
 * alone, and `--host= --user=` (a wrapper interpolating unset env vars) produce falsy
 * values while the flags were plainly given. Testing truthiness sent every one of them
 * down the soft path: a server that starts and looks healthy, with the explanation only
 * on a stderr stream an MCP client typically swallows. Only "asked for nothing" softens;
 * a half-given or empty-valued quick start is a typo and still refuses.
 */
function nothingRequested(argv: Argv): boolean {
  return !('host' in argv) && !('user' in argv);
}

export function parseArgv(args: string[] = process.argv.slice(2)): Argv {
  // Typed as Argv on the way out although any `--word` lands here: the keys are what
  // `checkUnknownFlags` exists to check, and everything after it may rely on the type.
  const config: Record<string, string | null> = {};
  for (const arg of args) {
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq === -1) {
        config[arg.slice(2)] = null;
      } else {
        config[arg.slice(2, eq)] = arg.slice(eq + 1);
      }
    }
  }
  return config;
}

/**
 * Whether a boolean flag was passed at all.
 *
 * `parseArgv` stores `null` for a flag written without `=`, which is how every
 * documented boolean flag is written. Testing that value for truthiness makes
 * the flag a no-op: `--disableApproval`, `--auditEntropyScan` and
 * `--auditTamperEvident` all did nothing unless spelled `--flag=1`, which
 * nothing documents (#91). The two call sites that got it right already used
 * `!== undefined`; this gives the check a name so the next one cannot miss it.
 *
 * `--flag=false` and `--flag=0` turn it off, because a flag that cannot be
 * turned off once written into a wrapper script is its own annoyance.
 */
/**
 * `--authFailureLimit`, refusing rather than guessing.
 *
 * `parseArgv` stores `null` for a flag written without a value, and `null !== undefined`,
 * so a bare `--authFailureLimit` reached `parseInt` and produced NaN. NaN fails the `> 0`
 * test the transport uses to decide whether to build the limiter at all, so a typo — or
 * `--authFailureLimit=off`, which `0 = off` makes a plausible spelling — silently turned
 * off a control that is on by default, with no line in the startup banner to say so. The
 * same shape on `--rateLimit` is harmless because that one defaults to off; this one does
 * not, which is what makes failing open new.
 */
export function parseFailureLimit(raw: string | null | undefined): number | undefined {
  if (raw === undefined) return undefined;
  if (raw === null || !/^\d+$/.test(raw.trim())) {
    throw new OperatorError(
      `--authFailureLimit needs a non-negative whole number, got ${JSON.stringify(raw)}. ` +
      'Use --authFailureLimit=0 to turn the check off deliberately.',
    );
  }
  const value = Number(raw.trim());
  // Bounded, because an unbounded one is the same fail-open this guard exists to stop:
  // `--authFailureLimit=99999999999999999999` parsed to 1e20, a bucket that never empties
  // and a `Retry-After` of 1 — configured on, functionally absent.
  if (!Number.isSafeInteger(value) || value > MAX_AUTH_FAILURE_LIMIT) {
    throw new OperatorError(
      `--authFailureLimit must be between 0 and ${MAX_AUTH_FAILURE_LIMIT}, got ${JSON.stringify(raw)}.`,
    );
  }
  return value;
}

/** `--httpSessionTtl`, refusing values that would silently disable idle eviction. */
export function parseHttpSessionTtl(raw: string | null | undefined): number | undefined {
  if (raw === undefined) return undefined;
  if (raw === null || !/^\d+$/.test(raw.trim())) {
    throw new OperatorError(
      `--httpSessionTtl needs a positive whole number of milliseconds, got ${JSON.stringify(raw)}.`,
    );
  }
  const value = Number(raw.trim());
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new OperatorError(
      `--httpSessionTtl must be a positive safe integer, got ${JSON.stringify(raw)}.`,
    );
  }
  return value;
}

/** Far above any real budget; the point is that there is one. */
const MAX_AUTH_FAILURE_LIMIT = 10_000;

export function flagEnabled(argv: Argv, name: Flag): boolean {
  const value = argv[name];
  if (value === undefined) return false;
  if (value === null || value === '') return true;
  return !['false', '0', 'no', 'off'].includes(value.toLowerCase());
}

/**
 * v1 flags that v2 removed. Silently ignoring them means the user only finds
 * out at the first command, as an auth failure with no hint about the cause.
 */
const REMOVED_V1_FLAGS: Record<string, string> = {
  password: 'Use the SSH_MCP_PASSWORD env var (or a per-profile SSH_MCP_<PROFILE>_PASSWORD).',
  suPassword: 'Use the SSH_MCP_SUDO_PASSWORD env var.',
  sudoPassword: 'Use the SSH_MCP_SUDO_PASSWORD env var.',
  disableSudo: 'Sudo is now a separate tool; restrict it with a role/policy that disallows the "privileged" class.',
};

/**
 * Every flag the server reads — the README's "CLI Flags (v2)" table, which a test holds
 * this list to.
 *
 * `Argv` is keyed by it, so reading a flag that is not listed here is a type error rather
 * than a flag the server refuses at startup.
 */
export const KNOWN_FLAGS = [
  'config', 'host', 'user', 'port', 'key', 'workdir', 'group',
  'timeout', 'maxChars', 'sessionMax', 'sessionTtl',
  'transport', 'httpPort', 'httpHost', 'bearerToken', 'rateLimit', 'httpSessionTtl',
  'authFailureLimit', 'trustProxy', 'trustedProxies', 'allowedHosts',
  'hostKeyMode', 'insecureHostKey',
  'allowUncheckedConfigAcl', 'strictConfigAcl',
  'disableApproval', 'opaUrl', 'opaFailClosed', 'opaTimeoutMs',
  'commandQuota', 'approvalGrantTtl',
  'auditEntropyScan', 'auditTamperEvident',
  'otelEndpoint', 'otelServiceName', 'dumpToolHashes',
] as const;

export type Flag = (typeof KNOWN_FLAGS)[number];

/** The command line as `parseArgv` reads it: `null` for a flag written without `=`. */
export type Argv = Partial<Record<Flag, string | null>>;

/** Any keys at all, for the two checks whose job is the keys `Argv` does not name. */
type RawArgv = Readonly<Record<string, string | null | undefined>>;

export function checkRemovedFlags(argv: RawArgv): void {
  const found = Object.keys(REMOVED_V1_FLAGS).filter((f) => f in argv);
  if (found.length === 0) return;
  throw new OperatorError(
    'These flags were removed in v2:\n' +
    found.map((f) => `  --${f}: ${REMOVED_V1_FLAGS[f]}`).join('\n') +
    '\nSee the "Migrating from v1" section of the README.',
  );
}

/**
 * Refuse a flag the server does not read, rather than drop it.
 *
 * `parseArgv` takes any `--word`, and nothing looked at the keys afterwards. The flag
 * this bit hardest is `--allowUncheckedConfigAcl`, the way out of a startup the server is
 * already refusing: misspelled, it produced the same refusal again with no sign anything
 * had been passed. Every unknown flag is named at once, so fixing them costs one restart.
 *
 * Removed v1 flags are left to `checkRemovedFlags`, which says what replaced them.
 */
export function checkUnknownFlags(argv: RawArgv): void {
  const known: readonly string[] = KNOWN_FLAGS;
  const unknown = Object.keys(argv).filter((f) => !known.includes(f) && !(f in REMOVED_V1_FLAGS));
  if (unknown.length === 0) return;
  const described = unknown.map((f) => {
    const near = nearestFlag(f);
    return near ? `--${f} (did you mean --${near}?)` : `--${f}`;
  });
  throw new OperatorError(
    `Unknown flag${unknown.length > 1 ? 's' : ''}: ${described.join(', ')}\n` +
    'The flags this server reads are listed under "CLI Flags (v2)" in the README.',
  );
}

/**
 * The known flag a misspelling most likely meant: at most two edits away, ignoring case,
 * so an all-lowercase spelling is distance 0. Two, because a closer bound misses a
 * transposition (`--hots`), which costs two.
 */
function nearestFlag(word: string): Flag | undefined {
  const lower = word.toLowerCase();
  let best: Flag | undefined;
  let bestDistance = 3;
  for (const f of KNOWN_FLAGS) {
    const d = editDistance(lower, f.toLowerCase());
    if (d < bestDistance) {
      best = f;
      bestDistance = d;
    }
  }
  return best;
}

function editDistance(a: string, b: string): number {
  let previous = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const current = [i];
    for (let j = 1; j <= b.length; j++) {
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
    previous = current;
  }
  return previous[b.length];
}

/**
 * v1 documented `--maxChars=none` (and 0/negative) as "no limit". Parsing it
 * with `parseInt(...) || 5000` silently turned that into a 5000-char cap.
 */
export function parseMaxChars(raw: string | null | undefined): number {
  if (typeof raw !== 'string' || raw === '') return 5_000;
  if (raw.toLowerCase() === 'none') return Number.MAX_SAFE_INTEGER;
  const parsed = parseInt(raw);
  if (isNaN(parsed)) return 5_000;
  return parsed <= 0 ? Number.MAX_SAFE_INTEGER : parsed;
}

/**
 * `--sessionTtl`, with `0` preserved as the documented "no idle expiry" value.
 *
 * `parseInt(...) || default` swallowed the 0 (falsy), so the one spelling a caller
 * would use to ask for an unlimited session silently became the 10-minute default —
 * the opposite of the request. Malformed input still falls back to the default.
 */
export function parseTtlMs(raw: string | null | undefined, fallback: number): number {
  if (typeof raw !== 'string' || raw === '') return fallback;
  const parsed = parseInt(raw);
  if (isNaN(parsed)) return fallback;
  return parsed < 0 ? fallback : parsed;
}

/**
 * `--opaTimeoutMs`, bounded on both sides.
 *
 * Too low turns an explicit OPA deny into an allow whenever the sidecar is slow, which is
 * the fail-open this budget exists inside; too high brings back the hang it replaced. One
 * second is the floor and two minutes the ceiling.
 */
export function parseOpaTimeout(raw: string | null | undefined): number | undefined {
  if (raw === undefined) return undefined;
  const value = raw === null ? NaN : Number(raw.trim());
  if (!Number.isSafeInteger(value) || value < 1_000 || value > 120_000) {
    throw new OperatorError(
      `--opaTimeoutMs must be a whole number of milliseconds between 1000 and 120000, got ${JSON.stringify(raw)}.`,
    );
  }
  return value;
}

/**
 * `--opaUrl`, refused at startup rather than at every request.
 *
 * Only emptiness was checked, so anything `fetch` cannot use reached the engine and failed
 * on every call — with `OPA sidecar enabled` printed at startup and one stderr line per
 * minute as the only signal. `--opaUrl=localhost:8181` is a realistic slip, since OPA's own
 * `--addr` is written `:8181`, and in the default mode it leaves a gate that looks
 * configured and is never consulted. Credentials in the URL are refused too: `fetch`
 * rejects such a URL outright, so it would be a gate that cannot work at all.
 */
export function parseOpaUrl(raw: string | null | undefined): string {
  if (!raw) {
    throw new OperatorError('--opaUrl needs a URL, as --opaUrl=http://localhost:8181.');
  }
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    throw new OperatorError(
      `--opaUrl=${raw} is not a URL. Include the scheme, as --opaUrl=http://localhost:8181.`,
    );
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new OperatorError(`--opaUrl must be http or https, got ${parsed.protocol}`);
  }
  if (parsed.username || parsed.password) {
    throw new OperatorError(
      '--opaUrl must not embed credentials — fetch() refuses such a URL, so the gate would ' +
      'never be consulted. Put the sidecar behind a network boundary instead.',
    );
  }
  // A trailing slash would make the request path `//v1/data/...`.
  return (parsed.origin + parsed.pathname).replace(/\/$/, '');
}

/**
 * `strict` was previously unreachable: nothing but test code could select it,
 * yet host-key.ts pointed users at a `--acceptNewHostKey` flag that never
 * existed. `--insecureHostKey` is kept as an alias for the documented flag.
 */
export function resolveHostKeyMode(argv: Argv): HostKeyMode {
  if (flagEnabled(argv, 'insecureHostKey')) return 'insecure';
  const mode = argv.hostKeyMode;
  if (mode === null || mode === undefined) return 'tofu';
  if (mode === 'tofu' || mode === 'strict' || mode === 'insecure') return mode;
  throw new OperatorError(`Invalid --hostKeyMode=${mode}. Expected one of: tofu, strict, insecure.`);
}

/** What `parseStartupFlags` hands to `main()`: the checked flags, absent where unused. */
export interface StartupFlags {
  hostKeyMode: HostKeyMode;
  opa?: { url: string; failClosed: boolean; timeoutMs: number | undefined };
  http?: { sessionIdleTtlMs: number | undefined; authFailureLimit: number | undefined };
}

/**
 * Every flag whose value is checked, parsed before the config load.
 *
 * They depend on argv alone, and the load can refuse — on Windows after running icacls.
 * Checked after it, a typo cost two restarts: fix what the loader refused, start again,
 * and only then learn the flag was misspelled.
 *
 * Under the same conditions as where they are used: a stdio run never read the HTTP
 * flags, and `--opaTimeoutMs` without `--opaUrl` was ignored, so refusing either now
 * would stop a start that works today.
 */
export function parseStartupFlags(argv: Argv): StartupFlags {
  const hostKeyMode = resolveHostKeyMode(argv);
  // Presence, not truthiness — the trap `flagEnabled` was written for. A space-separated
  // `--opaUrl http://…` stores null, so the old guard dropped it silently, and dropped
  // any `--opaFailClosed` the operator asked for with it.
  const failClosed = flagEnabled(argv, 'opaFailClosed');
  const opa = 'opaUrl' in argv
    ? { url: parseOpaUrl(argv.opaUrl), failClosed, timeoutMs: parseOpaTimeout(argv.opaTimeoutMs) }
    : undefined;
  if (!opa && failClosed) {
    throw new OperatorError('--opaFailClosed does nothing without --opaUrl.');
  }
  const http = argv.transport === 'http'
    ? {
        sessionIdleTtlMs: parseHttpSessionTtl(argv.httpSessionTtl),
        authFailureLimit: parseFailureLimit(argv.authFailureLimit),
      }
    : undefined;
  return { hostKeyMode, opa, http };
}

/**
 * Which policy tier a CLI-configured host belongs to.
 *
 * Without this there was no way to say it from the command line at all. The
 * inline profile carries no group, so it fell to the strictest tier, where the
 * `admin` role has no `privileged` — meaning `sudo` could never run for anyone
 * who had not written a config file (#91).
 *
 * The default stays `prod`. Guessing an unknown host is production is the safe
 * direction; what was missing was a way to correct the guess.
 */
export function resolveHostGroup(argv: Argv): string {
  const group = argv.group;
  if (group === null || group === undefined) return 'prod';
  if ((HOST_GROUPS as readonly string[]).includes(group)) return group;
  // Falling through would silently apply the prod bindings to a typo, and the
  // operator would read the refusal as policy rather than as their own slip.
  throw new OperatorError(
    `Invalid --group=${group}. Expected one of: ${HOST_GROUPS.join(', ')}.`,
  );
}

/**
 * The defaults a quick-start profile inherits, from flags alone.
 *
 * Named because an unconfigured start needs them too — `approvalGrantTtlMs` is read from
 * the registry's defaults, which exist long before any profile does, so the two paths have
 * to agree.
 */
export function defaultsFromArgv(argv: Argv): Defaults {
  return {
    sessionMaxPerConnection: parseInt(argv.sessionMax as string) || 5,
    sessionIdleTimeoutMs: parseTtlMs(argv.sessionTtl, 600_000),
    sessionBackgroundMaxMs: 3_600_000,
    commandTimeoutMs: parseInt(argv.timeout as string) || 60_000,
    commandMaxChars: parseMaxChars(argv.maxChars),
    commandMaxOutputBytes: 1_048_576,
    commandOutputTruncation: 'head',
    connectionIdleReapMs: 900_000,
    commandQuotaPerDay: parseInt(argv.commandQuota as string) || 0,
    approvalGrantTtlMs: parseInt(argv.approvalGrantTtl as string) || 0,
    approvalMode: 'ask-destructive',
    // No flag for transferRoot on purpose. It is the consent to touch local
    // disk, and the quick-start path exists for someone who passed a host and a
    // user on a command line — not a place to acquire that consent in passing.
    // The streaming file tools therefore refuse under `--host/--user` until a
    // config file names a root.
    transferMaxBytes: 268_435_456,
    transferTimeoutMs: 300_000,
  };
}

export function aclOptionsFromArgv(argv: Argv): AclOptions {
  // The way past an ACL that could not be read, rather than an operator with no
  // exit. See assertPrivateOnWindows.
  // The sink is supplied here rather than left to the module's default, which is the
  // point of having one: "this security check did not run" is a decision about what the
  // operator must be told, and the loader is not the layer that owns that. Routing it to
  // the audit store as well needs an AuditRecord variant for a startup event — that type
  // is hash-chained and tamper-evident, so it is its own change, and it is queued.
  //
  // An earlier version also pushed every finding into a module-level array "so main() can
  // act on them". Nothing ever read it, and this split made the claim impossible — main()
  // is in another module and the array was not exported. Re-adding a collection point is
  // one line when there is a consumer to write it against.
  return {
    enforce: flagEnabled(argv, 'strictConfigAcl'),
    allowUnchecked: flagEnabled(argv, 'allowUncheckedConfigAcl'),
    onFinding: (f: AclFinding) => {
      console.error(`Warning: ${f.message}`);
    },
  };
}

function loaded(config: AppConfig, source: ConfigSource, path: string, sha256: string | null): LoadedConfig {
  return { config, source, path, sha256, loadedAt: new Date().toISOString() };
}

/**
 * The startup config: from `--config`, the default path, or the quick-start flags, or
 * none at all. `aclOpts` is the ACL posture from argv; main() computes it once and hands
 * the same options to the reloader.
 */
export async function loadAppConfig(
  argv: Argv,
  aclOpts: AclOptions = aclOptionsFromArgv(argv),
): Promise<LoadedConfig> {
  if (argv.config !== undefined) {
    // `parseArgv` stores null for a flag written without `=`, so a bare `--config` used to
    // be falsy here and fall into the default-path branch — which now refuses rather than
    // silently ignoring an unusable file, so the operator got a refusal naming a path they
    // never asked for.
    if (argv.config === null || argv.config === '') {
      throw new OperatorError('--config needs a path: --config=<path>');
    }
    const { config, sha256 } = await loadConfigWithDigest(argv.config, aclOpts);
    return loaded(config, 'file', argv.config, sha256);
  }

  try {
    const { config: fromFile, sha256 } = await loadConfigWithDigest(undefined, aclOpts);
    // Before #138 every Windows config was rejected by the mode-bit check and
    // the rejection was swallowed, so an operator who also passed --host/--user
    // was silently running off the flags. Now that the file loads, it takes
    // precedence — a flip worth one line rather than a surprise about which host
    // a command reached.
    if (argv.host || argv.user) {
      console.error(
        `Note: ${getConfigPath()} was loaded, so --host/--user are ignored. ` +
        'Pass --config <path> to choose a different file.',
      );
    }
    return loaded(fromFile, 'file', getConfigPath(), sha256);
  } catch (err) {
    // Only "there is no file" means fall through. A file that exists and is
    // unusable — malformed TOML, a schema violation, a permission failure —
    // used to be swallowed here too and reported as a missing config, which is
    // how #138 stayed unfindable: the operator's file was in the right place,
    // and the real error was discarded before anyone could read it.
    //
    // Falling through would also be wrong on its own terms whenever
    // --host/--user happen to be present: the server would start, silently
    // ignoring every profile, policy and role binding the operator wrote.
    if (!(err instanceof ConfigNotFoundError)) throw err;
  }

  // Nothing configured, and nothing named on the command line either. Start anyway, with
  // no profiles: an MCP client or directory can then complete the handshake and read
  // `tools/list`, and every tool call is refused by `ConnectionRegistry` with the message
  // below — including `list-connections`, which resolves no profile and so had to be told.
  // `reload-config` is the exception, by design: it reaches no profile, and writing the
  // file then reloading is how a server started this way gets configured.
  //
  // Measured before this: `initialize` and `tools/list` against our own image drew no
  // JSON-RPC response at all — the process exited on this check first — so every directory
  // and every "add this server" flow saw a crash. Tool definitions are static metadata and
  // the config decides what they may *reach*, so coupling the two bought no safety.
  //
  // A half-given quick start is not this case: `--host` without `--user` is a typo, and an
  // explicit `--config` that points nowhere already threw above. Only "configured nothing"
  // softens — see `nothingRequested`, which tests for the flags being absent rather than
  // falsy so that a valueless or space-separated one stays a typo.
  if (nothingRequested(argv)) {
    console.error(`Warning: starting unconfigured — every tool call except reload-config will be refused until a config file is loaded.\n${new UnconfiguredError(getConfigPath()).message}`);
    return loaded({ defaults: defaultsFromArgv(argv), profiles: [] }, 'unconfigured', getConfigPath(), null);
  }

  if (!argv.host || !argv.user) {
    throw new UnconfiguredError(getConfigPath());
  }

  const defaults = defaultsFromArgv(argv);

  const profile: Profile = {
    name: 'default',
    host: argv.host,
    port: parseInt(argv.port as string) || 22,
    user: argv.user,
    auth: argv.key ? 'key' : 'password',
    keyRef: argv.key || undefined,
    workdir: argv.workdir || undefined,
    tty: false,
    timeout: defaults.commandTimeoutMs,
    maxChars: defaults.commandMaxChars,
    maxOutputBytes: defaults.commandMaxOutputBytes,
    outputTruncation: defaults.commandOutputTruncation,
    role: 'admin',
    group: resolveHostGroup(argv),
    readOnly: false,
    // Same default as the config schema. A CLI profile is the one-off case —
    // --host/--user with no config file — and it announces like any other.
    announceAgent: true,
    approvalPolicy: flagEnabled(argv, 'disableApproval') ? 'auto' : defaults.approvalMode,
    cert: false,
    sessionMaxPerConnection: defaults.sessionMaxPerConnection,
    sessionIdleTimeoutMs: defaults.sessionIdleTimeoutMs,
    sessionBackgroundMaxMs: defaults.sessionBackgroundMaxMs,
    commandQuotaPerDay: defaults.commandQuotaPerDay,
    transferMaxBytes: defaults.transferMaxBytes,
    transferTimeoutMs: defaults.transferTimeoutMs,
  };

  return loaded({ defaults, profiles: [profile] }, 'flags', getConfigPath(), null);
}

#!/usr/bin/env node

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { reportFatal } from './errors.js';
import { ConnectionRegistry } from './ssh/connection-registry.js';
import { PolicyEngine, resolvePolicyRules } from './policy/engine.js';
import { AuditStore } from './audit/store.js';
import { registerTools, registerResources, getToolHashes } from './tools/registry.js';
import { transferForbiddenDirs } from './tools/forbidden-dirs.js';
import { initKeychain } from './config/credential-resolver.js';
import { getConfigPath } from './config/loader.js';
import { SERVER_VERSION } from './version.js';
import { reapOnce } from './ssh/reaper.js';
import { ConfigReloader, installSighupReload } from './config/reload.js';
import {
  parseArgv,
  loadAppConfig,
  aclOptionsFromArgv,
  checkRemovedFlags,
  checkUnknownFlags,
  flagEnabled,
  parseStartupFlags,
} from './cli.js';

async function main() {
  const argv = parseArgv();
  // Removed flags first: they get the message that says what replaced them.
  checkRemovedFlags(argv);
  checkUnknownFlags(argv);

  if (argv.dumpToolHashes !== undefined) {
    console.log(JSON.stringify(getToolHashes(), null, 2));
    return;
  }

  // Before the config load; `parseStartupFlags` says why.
  const { hostKeyMode, opa, http } = parseStartupFlags(argv);

  // The whole of it, not just `config`: the reloader needs to know where the live config
  // came from, its hash and when it was loaded.
  // The ACL posture, once: startup's load and every reload check the file with it.
  const aclOptions = aclOptionsFromArgv(argv);
  const startup = await loadAppConfig(argv, aclOptions);
  const { config } = startup;
  const entropyScan = flagEnabled(argv, 'auditEntropyScan');
  const tamperEvident = flagEnabled(argv, 'auditTamperEvident');

  await initKeychain();

  if (argv.otelEndpoint) {
    const { initTracing } = await import('./observability/tracer.js');
    await initTracing(argv.otelEndpoint as string, (argv.otelServiceName as string) || 'ssh-mcp');
  }

  // Everything the transfer-root gate needs that it must not reach for itself:
  // which config file was actually loaded, and which directories are off limits.
  const localPath = {
    transferRoot: config.defaults.transferRoot,
    configPath: getConfigPath(argv.config || undefined),
    forbidden: transferForbiddenDirs(),
  };

  const registry = new ConnectionRegistry(config, hostKeyMode);
  const policy = new PolicyEngine(resolvePolicyRules(config.profiles, config.policy));
  const audit = new AuditStore(undefined, entropyScan, tamperEvident);

  if (opa) {
    policy.setOpaUrl(opa.url, opa.failClosed, opa.timeoutMs);
    console.error(`OPA sidecar enabled: ${argv.opaUrl}`);
  }

  // One reloader for the process: every MCP server below (one under stdio, one per HTTP
  // session) reloads the same registry, policy and transfer root, and the reloader
  // serializes them.
  const reloader = new ConfigReloader({ aclOptions, registry, policy, audit, localPath, startup });

  // An McpServer binds to a single transport, so HTTP needs one per session.
  const createMcpServer = (): McpServer => {
    // capabilities moved from serverInfo to ServerOptions in SDK 1.30.
    const server = new McpServer(
      { name: 'SSH MCP Server', version: SERVER_VERSION },
      { capabilities: { tools: {}, resources: {} } },
    );
    registerTools(server, registry, policy, audit, { localPath, reloader });
    registerResources(server, registry);
    return server;
  };

  const transportMode = argv.transport || 'stdio';

  if (transportMode === 'http') {
    const { startHttpServer } = await import('./transport/http.js');
    await startHttpServer(createMcpServer, {
      port: parseInt(argv.httpPort as string) || 3000,
      host: (argv.httpHost as string) || '127.0.0.1',
      bearerToken: argv.bearerToken as string | undefined,
      rateLimit: parseInt(argv.rateLimit as string) || 0,
      ...http,
      trustProxy: flagEnabled(argv, 'trustProxy'),
      trustedProxies: (argv.trustedProxies as string)?.split(',').map((h) => h.trim()).filter(Boolean),
      allowedHosts: (argv.allowedHosts as string)?.split(',').map((h) => h.trim()).filter(Boolean),
      registry,
    });
  } else {
    const transport = new StdioServerTransport();
    await createMcpServer().connect(transport);
    console.error('SSH MCP Server v2 running on stdio');
  }

  const reaperInterval = setInterval(() => {
    // Session-then-connection ordering (load-bearing) is documented in `reapOnce`.
    void reapOnce(registry).catch((err) => console.error('reaper failed:', err));
  }, 60_000);

  /**
   * How long teardown gets before the process exits regardless.
   *
   * One kill ladder (3s) plus slack. Sessions and connections close concurrently, so this
   * is the whole budget rather than a per-session one. Docker's default stop grace is 10s
   * and Kubernetes' is 30s, so this stays comfortably inside both — the point is that we
   * choose the moment we give up rather than being SIGKILLed in the middle of it.
   */
  const SHUTDOWN_BUDGET_MS = 5000;

  let isShuttingDown = false;
  const cleanup = async () => {
    if (isShuttingDown) return;
    isShuttingDown = true;
    console.error('Shutting down SSH MCP Server...');
    clearInterval(reaperInterval);
    // Audit first. An earlier version of this comment claimed session teardown wrote audit
    // records that the old order dropped — it does not: nothing under src/ssh/ touches the
    // audit store, only the `close-session` tool does, and that record is written and
    // awaited during the tool call. So the reorder rescued nothing and put the final flush
    // behind a teardown that now waits for kill ladders. Flushing first cannot lose a record
    // that teardown does not write, and it survives a SIGKILL at the end of the grace period.
    try { await audit.close(); } catch (e) { console.error('audit.close failed:', e); }
    // Bounded, so `process.exit(0)` is reached deliberately rather than by the container
    // runtime's SIGKILL. Teardown is concurrent now, so the honest ceiling is one kill
    // ladder plus slack rather than one per session.
    try {
      await Promise.race([
        registry.closeAll(),
        new Promise((resolve) => setTimeout(resolve, SHUTDOWN_BUDGET_MS).unref()),
      ]);
    } catch (e) { console.error('closeAll failed:', e); }
    process.exit(0);
  };

  if (transportMode !== 'http') {
    // The SDK's stdio transport listens only for 'data' and 'error', so a
    // client that exits without signalling leaves this process running with
    // its SSH connections open. Treat EOF on stdin as the client going away.
    const onStdinClosed = () => { void cleanup(); };
    process.stdin.on('end', onStdinClosed);
    process.stdin.on('close', onStdinClosed);
  }

  process.on('SIGINT', cleanup);
  process.on('SIGTERM', cleanup);
  // Before this, SIGHUP's default action killed the process without flushing the audit
  // log. Now it reloads the config, except on Windows; see installSighupReload.
  installSighupReload(reloader);
}

const isTestMode = process.env.SSH_MCP_TEST === '1';
const isCliEnabled = process.env.SSH_MCP_DISABLE_MAIN !== '1';

if (isCliEnabled || isTestMode) {
  main().catch((error) => {
    process.exit(reportFatal(error));
  });
}

